package io.ivo.mp3;
import java.io.*;import java.util.*;import java.util.zip.*;
/** Exact integer Layer III syntax IR. No dequantization, rounding or audio transcoding. */
final class SpectralIr {
 record Part(int length,int big,int scfc,int block,boolean mixed,int[] tables,int r0,int r1,int count1,int scfsi,int[] bands,boolean mpeg1,boolean intensity,int globalGain,int scaleShift,boolean preflag,int[] subGain,boolean midSide){
 Part(int length,int big,int scfc,int block,boolean mixed,int[] tables,int r0,int r1,int count1,int scfsi,int[] bands,boolean mpeg1,boolean intensity,int globalGain){this(length,big,scfc,block,mixed,tables,r0,r1,count1,scfsi,bands,mpeg1,intensity,globalGain,1,false,new int[3],false);}
}
 record Side(int back,List<Part> parts){}
 static final HuffmanCodes.Code[][] CODES=new HuffmanCodes.Code[32][];
 static final HuffmanCodes.Code[][] QUADS=new HuffmanCodes.Code[2][16];
 static {for(int t=0;t<32;t++)if(t!=4&&t!=14)CODES[t]=HuffmanCodes.codes(t);for(int t=0;t<2;t++)for(int pattern=0;pattern<64;pattern++){int leaf=quadLeaf(t,pattern,6),n=leaf&7,symbol=leaf>>>4;var c=new HuffmanCodes.Code(pattern>>>(6-n),n);if(QUADS[t][symbol]!=null&&!QUADS[t][symbol].equals(c))throw new AssertionError("Quad table");QUADS[t][symbol]=c;}}
 static int quadLeaf(int t,int peek,int width){if(t==1)return SpectralTables.QUAD33[peek>>>(width-4)];int leaf=SpectralTables.QUAD32[peek>>>(width-4)];if((leaf&8)==0){int n=leaf&3;leaf=SpectralTables.QUAD32[(leaf>>>3)+((peek>>>(width-4-n))&((1<<n)-1))];}return leaf;}
 static final class Bits {final byte[] data;int pos;final int end;Bits(byte[] data,int start,int end){if(start<0||end<start||end>data.length*8L)throw new IllegalArgumentException("Bit bounds");this.data=data;pos=start;this.end=end;}int read(int n){if(n<0||n>24||pos+n>end)throw new IllegalArgumentException("Part underflow");int v=peek(n);pos+=n;return v;}int peek(int n){int v=0;for(int i=0;i<n;i++)v=(v<<1)|(pos+i<end?(data[(pos+i)/8]>>>(7-(pos+i)%8))&1:0);return v;}}
 static final class Emit {final byte[] data;int pos;final int end;Emit(byte[] data,int start,int end){this.data=data;pos=start;this.end=end;}void put(int v,int n){if(n<0||n>24||pos+n>end)throw new IllegalArgumentException("Emit bounds");for(int i=n-1;i>=0;i--,pos++)if(((v>>>i)&1)!=0)data[pos/8]|=(byte)(1<<(7-pos%8));}}
 static Side side(byte[] bytes,int at,int size,byte[] headers,int frame,int version,boolean mono){boolean mpeg1=version==1;int channels=mono?1:2;Bits b=new Bits(bytes,at*8,(at+size)*8);int back=b.read(mpeg1?9:8);b.read(mpeg1?(mono?5:3):channels);int[] flags=new int[channels];if(mpeg1)for(int c=0;c<channels;c++)flags[c]=b.read(4);
  int h1=headers[frame*4+1]&255,h2=headers[frame*4+2]&255,h3=headers[frame*4+3]&255;int sr=((h2>>>2)&3)+(((h1>>>3)&1)+((h1>>>4)&1))*3;if(sr!=0)sr--;if(sr>7)throw new IllegalArgumentException("Sample rate");List<Part> parts=new ArrayList<>();
  for(int gr=0;gr<(mpeg1?2:1);gr++)for(int ch=0;ch<channels;ch++){int length=b.read(12),big=b.read(9);if(big>288)throw new IllegalArgumentException("Big values");int globalGain=b.read(8);int scfc=b.read(mpeg1?4:9),switched=b.read(1),block=0;boolean mixed=false;int[] tabs=new int[3],subGain=new int[3];int r0,r1;int[] bands=SpectralTables.LONG[sr];if(switched!=0){block=b.read(2);if(block==0)throw new IllegalArgumentException("Block type");mixed=b.read(1)!=0;tabs[0]=b.read(5);tabs[1]=b.read(5);for(int i=0;i<3;i++)subGain[i]=b.read(3);r0=7;r1=255;if(block==2){if(mixed)bands=SpectralTables.MIXED[sr];else{bands=SpectralTables.SHORT[sr];r0=8;}}}else{for(int i=0;i<3;i++)tabs[i]=b.read(5);r0=b.read(4);r1=b.read(3);}boolean preflag=mpeg1?b.read(1)!=0:scfc>=500;int scaleShift=1+b.read(1);int count1=b.read(1);int scfsi=mpeg1&&gr==1&&block!=2?flags[ch]:0;boolean intensity=!mpeg1&&ch==1&&(h3>>>6)==1&&(h3&16)!=0;parts.add(new Part(length,big,scfc,block,mixed,tabs,r0,r1,count1,scfsi,bands,mpeg1,intensity,globalGain,scaleShift,preflag,subGain,(h3>>>6)==1&&(h3&32)!=0));}
  if(b.pos!=b.end)throw new IllegalArgumentException("Side trailing bits");return new Side(back,List.copyOf(parts));
 }
 static int[] widths(Part p){int kind=p.block==2?(p.mixed?1:2):0;int[] widths=new int[4];int offset=0;if(p.mpeg1){int[] decode={0,1,2,3,12,5,6,7,9,10,11,13,14,15,18,19};int v=decode[p.scfc];widths[0]=widths[1]=v>>>2;widths[2]=widths[3]=v&3;}else{int[] mod={5,5,4,4,5,5,4,1,4,3,1,1,5,6,6,1,4,4,4,1,4,3,1,1};int k=p.intensity?12:0,sfc=p.scfc>>(p.intensity?1:0),product=0;do{if(k>=mod.length)throw new IllegalArgumentException("Scalefactors");product=1;for(int i=3;i>=0;i--){widths[i]=sfc/product%mod[k+i];product*=mod[k+i];}sfc-=product;k+=4;}while(sfc>=0);offset=k;}
  ArrayList<Integer> result=new ArrayList<>();for(int i=0;i<4;i++){int count=SpectralTables.PARTITIONS[kind][offset+i];if(count==0)break;if(p.mpeg1&&(p.scfsi&(8>>>i))!=0)continue;for(int n=0;n<count;n++)if(widths[i]!=0)result.add(widths[i]);}return result.stream().mapToInt(Integer::intValue).toArray();
 }
 static int table(Part p,int pair){int bound=0;for(int i=0;i<=p.r0&&i<p.bands.length;i++)bound+=p.bands[i];if(pair*2<bound)return p.tables[0];int end=bound;for(int i=p.r0+1;i<=p.r0+p.r1+1&&i<p.bands.length;i++)end+=p.bands[i];return pair*2<end?p.tables[1]:p.tables[2];}
 static int[] pair(Bits b,int t){if(t==4||t==14||t<0||t>31)throw new IllegalArgumentException("Reserved Huffman table");int base=HuffmanLookup.INDEX[t],w=5,leaf=HuffmanLookup.TABS[base+b.peek(w)];while(leaf<0){b.read(w);w=leaf&7;leaf=HuffmanLookup.TABS[base+b.peek(w)-(leaf>>3)];}b.read(leaf>>>8);int[] values=new int[2];for(int i=0;i<2;i++){int v=(leaf>>>(4*i))&15;if(v==15&&HuffmanLookup.LINBITS[t]>0)v+=b.read(HuffmanLookup.LINBITS[t]);if(v!=0&&b.read(1)!=0)v=-v;values[i]=v;}return values;}
 static void pair(Emit b,int t,int x,int y){if(t<0||t>31||CODES[t]==null)throw new IllegalArgumentException("Pair table");int lin=HuffmanLookup.LINBITS[t],ax=Math.abs(x),ay=Math.abs(y);if(ax>15+(lin>0?(1<<lin)-1:0)||ay>15+(lin>0?(1<<lin)-1:0))throw new IllegalArgumentException("Pair range");var c=CODES[t][Math.min(ax,15)|(Math.min(ay,15)<<4)];if(c==null)throw new IllegalArgumentException("Pair unavailable");b.put(c.bits(),c.width());for(int v:new int[]{x,y}){int a=Math.abs(v);if(a>=15&&lin>0)b.put(a-15,lin);if(a!=0)b.put(v<0?1:0,1);}}
 static int[] quad(Bits b,int t){int leaf=quadLeaf(t,b.peek(6),6);b.read(leaf&7);int[] a=new int[4];for(int i=0;i<4;i++)if((leaf&(128>>>i))!=0)a[i]=b.read(1)==0?1:-1;return a;}
 static void quad(Emit b,int t,int code){if(code<0||code>=81)throw new IllegalArgumentException("Quad value");int[] a=new int[4];int mask=0;for(int i=0;i<4;i++){int v=code%3;code/=3;a[i]=v==2?-1:v;if(v!=0)mask|=8>>>i;}var c=QUADS[t][mask];b.put(c.bits(),c.width());for(int v:a)if(v!=0)b.put(v<0?1:0,1);}
 static int ternary(int[] a){int value=0,m=1;for(int v:a){value+=m*(v<0?2:v);m*=3;}return value;}
 static void number(OutputStream out,int n)throws IOException{if(n<0)throw new IllegalArgumentException("Negative IR");while(n>=128){out.write((n&127)|128);n>>>=7;}out.write(n);}
 static int number(InputStream in)throws IOException{int v=0;for(int s=0;s<=28;s+=7){int b=in.read();if(b<0)throw new EOFException();if(s==28&&(b&248)!=0)throw new IOException("IR overflow");v|=(b&127)<<s;if(b<128)return v;}throw new IOException("IR varint");}
 static int signed(InputStream in)throws IOException{int z=number(in);return(z>>>1)^-(z&1);}
 static void signed(OutputStream out,int n)throws IOException{number(out,(n<<1)^(n>>31));}
 static void raw(OutputStream out,Bits bits,int end)throws IOException{int n=end-bits.pos;number(out,n);while(n>0){int width=Math.min(8,n);out.write(bits.read(width));n-=width;}}
 static void raw(InputStream in,Emit emit,int expected)throws IOException{int n=number(in);if(n!=expected)throw new IOException("Raw bit count");while(n>0){int width=Math.min(8,n),value=in.read();if(value<0||value>=(1<<width))throw new IOException("Raw bits");emit.put(value,width);n-=width;}}
 record Stats(long parts,long pairs,long quads,long scalefactorBits,long residualBits,long unusedBits,long bigHash,long quadHash){}
 static final class Counts {long parts,pairs,quads,scales,residual,unused,hash=0xcbf29ce484222325L,qhash=0xcbf29ce484222325L;Stats stats(){return new Stats(parts,pairs,quads,scales,residual,unused,hash,qhash);}void value(int v){hash=(hash^(v&0xffffffffL))*0x100000001b3L;}}
 static byte[] encode(ReservoirTrial.Ir ir,Counts counts)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();Deflater deflater=new Deflater(9);try(DeflaterOutputStream out=new DeflaterOutputStream(bytes,deflater,65536)){walk(ir,out,null,counts);}finally{deflater.end();}return bytes.toByteArray();}
 static byte[] decode(ReservoirTrial.Ir ir,byte[] compressed,Counts counts)throws IOException{byte[] restored=new byte[ir.mainData().length];try(InflaterInputStream in=new InflaterInputStream(new ByteArrayInputStream(compressed))){walk(ir,null,new Decode(in,restored),counts);if(in.read()!=-1)throw new IOException("Trailing spectral IR");}return restored;}
 record Decode(InputStream in,byte[] target){}
 static void walk(ReservoirTrial.Ir ir,OutputStream out,Decode decode,Counts stats)throws IOException{int frame=0,sp=0,mp=0,cursor=0;byte[] main=ir.mainData();for(var f:ir.frames()){Side side=side(ir.sideInfo(),sp,f.sideInfoBytes(),ir.headers(),frame,f.version(),f.mono());int start=Math.multiplyExact(mp-side.back,8),physicalEnd=Math.multiplyExact(mp+f.mainBytes(),8);if(start<0||start>physicalEnd)throw new IllegalArgumentException("Invalid reservoir");for(Part p:side.parts){int end=Math.addExact(start,p.length);if(end>physicalEnd||end>start&&start<cursor)throw new IllegalArgumentException("Invalid spectral interval");if(end==start){if(widths(p).length!=0)throw new IllegalArgumentException("Empty scale part");for(int i=0;i<p.big;i++){if(table(p,i)!=0)throw new IllegalArgumentException("Empty Huffman part");stats.pairs++;stats.value(0);stats.value(0);}stats.parts++;start=end;continue;}
   stats.unused+=start-cursor;if(out!=null)raw(out,new Bits(main,cursor,start),start);else raw(decode.in,new Emit(decode.target,cursor,start),start-cursor);
   Bits bits=out!=null?new Bits(main,start,end):null;Emit emit=decode!=null?new Emit(decode.target,start,end):null;
   for(int width:widths(p)){stats.scales+=width;if(out!=null)out.write(bits.read(width));else{int v=decode.in.read();if(v<0||v>=(1<<width))throw new IOException("Scale value");emit.put(v,width);}}
   for(int i=0;i<p.big;i++){int tab=table(p,i);if(out!=null){int[] a=pair(bits,tab);signed(out,a[0]);signed(out,a[1]);stats.value(a[0]);stats.value(a[1]);}else{int x=signed(decode.in),y=signed(decode.in);pair(emit,tab,x,y);stats.value(x);stats.value(y);}stats.pairs++;}
   if(out!=null){ByteArrayOutputStream quads=new ByteArrayOutputStream();for(int used=2*p.big;used+4<=576;used+=4){int saved=bits.pos;try{quads.write(ternary(quad(bits,p.count1)));}catch(IllegalArgumentException e){bits.pos=saved;break;}}number(out,quads.size());byte[] qbytes=quads.toByteArray();out.write(qbytes);for(byte q:qbytes)stats.qhash=(stats.qhash^(q&255))*0x100000001b3L;stats.quads+=quads.size();stats.residual+=end-bits.pos;raw(out,bits,end);}else{int n=number(decode.in);if(n>(576-2*p.big)/4)throw new IOException("Count1 count");for(int i=0;i<n;i++){int v=decode.in.read();if(v<0)throw new EOFException();quad(emit,p.count1,v);stats.qhash=(stats.qhash^v)*0x100000001b3L;}stats.quads+=n;stats.residual+=end-emit.pos;raw(decode.in,emit,end-emit.pos);}
   stats.parts++;cursor=end;start=end;
  }sp+=f.sideInfoBytes();mp+=f.mainBytes();frame++;}
  int limit=main.length*8;stats.unused+=limit-cursor;if(out!=null)raw(out,new Bits(main,cursor,limit),limit);else raw(decode.in,new Emit(decode.target,cursor,limit),limit-cursor);
 }
}
